import{_ as e,o as i,c as l,a0 as o}from"./chunks/framework.D0gLf8u5.js";const p=JSON.parse('{"title":"部署指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide/deployment.md","filePath":"guide/deployment.md","lastUpdated":null}'),t={name:"guide/deployment.md"};function r(d,a,n,s,u,h){return i(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="部署指南" tabindex="-1">部署指南 <a class="header-anchor" href="#部署指南" aria-label="Permalink to &quot;部署指南&quot;">​</a></h1><p>云族纪是<strong>私有部署</strong>的应用——每个家族自己部署一套，数据只属于自己。</p><h2 id="前置要求" tabindex="-1">前置要求 <a class="header-anchor" href="#前置要求" aria-label="Permalink to &quot;前置要求&quot;">​</a></h2><ul><li>HBuilderX（开发工具）</li><li>uniCloud 阿里云空间（免费额度足够）</li><li>Node.js（本地开发用）</li></ul><h2 id="部署步骤" tabindex="-1">部署步骤 <a class="header-anchor" href="#部署步骤" aria-label="Permalink to &quot;部署步骤&quot;">​</a></h2><h3 id="_1-获取代码" tabindex="-1">1. 获取代码 <a class="header-anchor" href="#_1-获取代码" aria-label="Permalink to &quot;1. 获取代码&quot;">​</a></h3><p>从 Gitee 或 GitHub 克隆项目：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://gitee.com/hy_ATfield/YunZuJi.git</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_2-导入-hbuilderx" tabindex="-1">2. 导入 HBuilderX <a class="header-anchor" href="#_2-导入-hbuilderx" aria-label="Permalink to &quot;2. 导入 HBuilderX&quot;">​</a></h3><p>用 HBuilderX 打开项目文件夹。</p><h3 id="_3-创建-unicloud-空间" tabindex="-1">3. 创建 uniCloud 空间 <a class="header-anchor" href="#_3-创建-unicloud-空间" aria-label="Permalink to &quot;3. 创建 uniCloud 空间&quot;">​</a></h3><p>在 HBuilderX 里：</p><ol><li>右键 <code>uniCloud-aliyun</code> 目录</li><li>选择&quot;关联云服务空间或项目&quot;</li><li>创建新的阿里云空间（免费额度即可）</li></ol><h3 id="_4-上传云函数" tabindex="-1">4. 上传云函数 <a class="header-anchor" href="#_4-上传云函数" aria-label="Permalink to &quot;4. 上传云函数&quot;">​</a></h3><p>右键每个云函数目录，选择&quot;上传部署&quot;：</p><ul><li><code>api-family</code></li><li><code>api-tree</code></li><li><code>api-identity</code></li><li><code>api-transfer</code></li><li><code>api-record</code></li><li><code>api-user</code></li><li><code>yz-family-core</code></li></ul><blockquote><p>首次上传时需要安装云端依赖，按提示确认即可。</p></blockquote><h3 id="_5-初始化数据库" tabindex="-1">5. 初始化数据库 <a class="header-anchor" href="#_5-初始化数据库" aria-label="Permalink to &quot;5. 初始化数据库&quot;">​</a></h3><p>云函数上传后，schema 会自动初始化。首次访问应用时，系统会引导你完成：</p><ol><li>注册账号</li><li>创建家族</li><li>录入始祖</li><li>开始添加成员</li></ol><h3 id="_6-编译运行" tabindex="-1">6. 编译运行 <a class="header-anchor" href="#_6-编译运行" aria-label="Permalink to &quot;6. 编译运行&quot;">​</a></h3><p>在 HBuilderX 里选择运行平台：</p><ul><li><strong>H5</strong>：浏览器里直接看</li><li><strong>微信小程序</strong>：微信开发者工具里看</li><li><strong>App</strong>：打包成手机 App</li></ul><hr><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>部署完成后，第一个注册的人自动成为家族管理员</li><li>家族数据存在你自己的 uniCloud 空间里，不在我们的服务器上</li><li>建议定期导出 CSV 备份家族数据</li></ul>',26)])])}const b=e(t,[["render",r]]);export{p as __pageData,b as default};
